package com.music.spotui.data.preferences

/*
 * Appearance choices on top of the look: the wallpaper's colours (Material You) for the Classic
 * look, and the font of both looks. Compose state, so every screen redraws when one changes.
 */

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.graphics.Color

private const val PREF = "settings_prefs"

private fun prefs(c: Context) = c.getSharedPreferences(PREF, Context.MODE_PRIVATE)

/**
 * "Dynamic colors (Material You)": the Classic look's accent taken from the wallpaper (Android 12
 * and later), in place of the accent chosen in the settings. Off by default. The Immersive look
 * keeps its own colours, taken from the playing cover.
 */
object DynamicColorPref {
    private const val KEY = "dynamic_color"

    /** The phone has wallpaper colours to give (Android 12 and later). */
    val available: Boolean get() = android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S

    var on by mutableStateOf(prefs(com.music.spotui.di.Graph.app).getBoolean(KEY, false))
        private set

    /** On, and the phone can give the colours. */
    val active: Boolean get() = on && available

    fun set(c: Context, value: Boolean) {
        on = value
        cached = null
        prefs(c).edit().putBoolean(KEY, value).apply()
    }

    // The wallpaper's accent, read once per configuration (see [refresh]): it is asked at every draw.
    @Volatile private var cached: Color? = null

    /** The configuration changed (a new wallpaper recreates the activity): the accent is read again. */
    fun refresh() { cached = null }

    /**
     * The wallpaper's accent for the Classic look, or null (off, Immersive, before Android 12). The
     * same tone Material's dynamic dark scheme gives its primary colour (system_accent1_200).
     */
    fun accent(): Color? {
        if (!on || android.os.Build.VERSION.SDK_INT < android.os.Build.VERSION_CODES.S || LookPref.look != Look.CLASSIC) return null
        cached?.let { return it }
        return runCatching { Color(com.music.spotui.di.Graph.app.getColor(android.R.color.system_accent1_200)) }
            .getOrNull()?.also { cached = it }
    }
}

/**
 * "App font": Myspoti's own fonts (Manrope in the Classic look, Inter in the Immersive one, the
 * default) or the phone's system font. No font is bundled for it: the system one is the phone's.
 */
object AppFontPref {
    private const val KEY = "system_font"

    /** True: the phone's system font everywhere in the app. */
    var system by mutableStateOf(prefs(com.music.spotui.di.Graph.app).getBoolean(KEY, false))
        private set

    fun set(c: Context, value: Boolean) {
        system = value
        prefs(c).edit().putBoolean(KEY, value).apply()
    }
}

/**
 * "Download lyrics with songs": a downloaded song's lyrics are looked up and kept with it, so the
 * lyrics show without a connection. On by default.
 */
object LyricsOfflinePref {
    private const val KEY = "download_lyrics"

    var on by mutableStateOf(prefs(com.music.spotui.di.Graph.app).getBoolean(KEY, true))
        private set

    fun set(c: Context, value: Boolean) {
        on = value
        prefs(c).edit().putBoolean(KEY, value).apply()
    }
}

package com.music.spotui.data.preferences

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.music.spotui.di.EqBands
import com.music.spotui.di.EqTuning
import com.music.spotui.di.Equalizer
import com.music.spotui.di.Spatial

/** The equalizer's ready-made curves: ten band gains and the preamp that keeps them under full scale, in dB. */
enum class EqPreset(val gains: FloatArray, val preamp: Float) {
    FLAT(floatArrayOf(0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f), 0f),
    BASS_BOOST(floatArrayOf(6f, 5f, 4f, 2f, 0f, 0f, 0f, 0f, 0f, 0f), -5f),
    BASS_CUT(floatArrayOf(-6f, -5f, -4f, -2f, 0f, 0f, 0f, 0f, 0f, 0f), 0f),
    TREBLE_BOOST(floatArrayOf(0f, 0f, 0f, 0f, 0f, 1f, 2f, 4f, 5f, 6f), -5f),
    TREBLE_CUT(floatArrayOf(0f, 0f, 0f, 0f, 0f, -1f, -2f, -4f, -5f, -6f), 0f),
    VOCAL(floatArrayOf(-2f, -2f, -1f, 0f, 2f, 4f, 4f, 2f, 0f, -1f), -3f),
    ROCK(floatArrayOf(5f, 4f, 2f, -1f, -2f, -1f, 1f, 3f, 4f, 5f), -4f),
    POP(floatArrayOf(-1f, 1f, 3f, 4f, 3f, 0f, -1f, -1f, 1f, 2f), -3f),
    JAZZ(floatArrayOf(3f, 2f, 1f, 2f, -1f, -1f, 0f, 1f, 2f, 3f), -2f),
    CLASSICAL(floatArrayOf(3f, 2f, 1f, 0f, 0f, 0f, -1f, -1f, 1f, 2f), -2f),
    ELECTRONIC(floatArrayOf(5f, 4f, 1f, 0f, -2f, 1f, 0f, 1f, 4f, 5f), -4f),
    HIP_HOP(floatArrayOf(5f, 4f, 2f, 3f, -1f, -1f, 1f, -1f, 2f, 3f), -4f),
    ACOUSTIC(floatArrayOf(4f, 4f, 3f, 1f, 2f, 1f, 3f, 3f, 3f, 2f), -4f),
    SPOKEN_WORD(floatArrayOf(-4f, -3f, 0f, 1f, 3f, 4f, 4f, 3f, 1f, -2f), -3f),
    /** The user's own curve (a band or the preamp moved by hand). */
    CUSTOM(FloatArray(10), 0f),
}

/**
 * The equalizer, speed and silence skipping of the local player (ExoPlayer: extensions' streams,
 * downloads, the phone's files). Spotify's own songs play in the Web Player, whose decoded sound
 * the app never gets: none of this applies to them, nor to a Cast device. Kept across launches.
 *
 * Speed: 0.5× to 2× for everything the local player plays, 1× by default (podcasts streamed by
 * Spotify keep their own speed, the podcast player's). Off 1×, Spotify does not follow the song
 * (see AccountSync): its page plays at 1× only.
 *
 * Spatial audio: the stereo widened by mid/side processing (see SpatialProcessor), off by default,
 * on its own switch (the equalizer may be off).
 */
object EqualizerPref {
    private const val PREF = "equalizer_prefs"
    private fun prefs(c: Context) = c.getSharedPreferences(PREF, Context.MODE_PRIVATE)
    private val p get() = prefs(com.music.spotui.di.Graph.app)

    val SPEEDS = listOf(0.5f, 0.75f, 1f, 1.25f, 1.5f, 1.75f, 2f)

    var enabled by mutableStateOf(p.getBoolean("enabled", false))
        private set
    var preset by mutableStateOf(runCatching { EqPreset.valueOf(p.getString("preset", null) ?: "FLAT") }.getOrDefault(EqPreset.FLAT))
        private set
    private var customGains by mutableStateOf(FloatArray(EqBands.COUNT) { p.getFloat("gain$it", 0f) })
    private var customPreamp by mutableStateOf(p.getFloat("preamp", 0f))
    var speed by mutableStateOf(p.getFloat("speed", 1f).coerceIn(0.5f, 2f))
        private set
    var skipSilence by mutableStateOf(p.getBoolean("skip_silence", false))
        private set
    var spatial by mutableStateOf(p.getBoolean("spatial", false))
        private set
    var spatialWidth by mutableStateOf(p.getFloat("spatial_width", Spatial.DEFAULT_WIDTH).coerceIn(Spatial.MIN_WIDTH, Spatial.MAX_WIDTH))
        private set

    /** The gains shown and heard: the preset's, or the user's own. */
    val gains: FloatArray get() = if (preset == EqPreset.CUSTOM) customGains else preset.gains
    val preamp: Float get() = if (preset == EqPreset.CUSTOM) customPreamp else preset.preamp

    init { push() }

    fun setEnabled(c: Context, on: Boolean) {
        enabled = on
        prefs(c).edit().putBoolean("enabled", on).apply()
        push()
    }

    fun setPreset(c: Context, value: EqPreset) {
        // Custom picked from the list: the curve last made by hand.
        preset = value
        prefs(c).edit().putString("preset", value.name).apply()
        push()
    }

    /**
     * A band moved by hand: the curve shown becomes the user's own, from where it was. Heard at
     * once; kept when [save] (a slider saves once, at the end of its drag, see [save]).
     */
    fun setGain(c: Context, band: Int, db: Float, save: Boolean = true) {
        if (band !in 0 until EqBands.COUNT) return
        val g = gains.copyOf().also { it[band] = db.coerceIn(EqBands.MIN_DB, EqBands.MAX_DB) }
        custom(c, g, preamp, save)
    }

    fun setPreamp(c: Context, db: Float, save: Boolean = true) =
        custom(c, gains.copyOf(), db.coerceIn(EqBands.PREAMP_MIN_DB, EqBands.PREAMP_MAX_DB), save)

    private fun custom(c: Context, g: FloatArray, pre: Float, save: Boolean) {
        customGains = g; customPreamp = pre; preset = EqPreset.CUSTOM
        push()
        if (save) save(c)
    }

    /** Keeps the user's own curve as it is now. */
    fun save(c: Context) {
        prefs(c).edit().apply {
            customGains.forEachIndexed { i, v -> putFloat("gain$i", v) }
            putFloat("preamp", customPreamp); putString("preset", preset.name)
        }.apply()
    }

    fun setSpeed(c: Context, value: Float) {
        speed = value.coerceIn(0.5f, 2f)
        prefs(c).edit().putFloat("speed", speed).apply()
        com.music.spotui.di.LocalPlayer.applyPlayback()
        // Spotify's page plays at 1× only: the listen sync stops off 1×, and starts again at 1×.
        com.music.spotui.di.AccountSync.listen.refresh()
    }

    fun setSkipSilence(c: Context, on: Boolean) {
        skipSilence = on
        prefs(c).edit().putBoolean("skip_silence", on).apply()
        com.music.spotui.di.LocalPlayer.applyPlayback()
    }

    fun setSpatial(c: Context, on: Boolean) {
        spatial = on
        prefs(c).edit().putBoolean("spatial", on).apply()
        push()
    }

    /** Heard at once, gliding; kept when [save] (a slider saves once, at the end of its drag). */
    fun setSpatialWidth(c: Context, value: Float, save: Boolean = true) {
        spatialWidth = value.coerceIn(Spatial.MIN_WIDTH, Spatial.MAX_WIDTH)
        push()
        if (save) prefs(c).edit().putFloat("spatial_width", spatialWidth).apply()
    }

    /** Hands the curve and the width to the players' audio stages (read on their audio threads). */
    private fun push() {
        Equalizer.current = if (enabled) EqTuning(gains, preamp) else null
        Spatial.current = if (spatial) spatialWidth else null
        // The audio offload is allowed only with both doing nothing.
        com.music.spotui.di.LocalPlayer.applyOffload()
    }
}

package com.music.spotui.data.preferences

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.music.spotui.data.entity.SongsModel
import org.json.JSONArray
import org.json.JSONObject

/** A song marked "Not interested": enough to list it in Settings and show it again. */
data class HiddenSong(val id: String, val title: String, val singer: String, val coverUri: String)

/**
 * "Not interested", as YouTube Music's dislike: a list that stays on this phone (nothing is sent to
 * Spotify). A hidden song is skipped when a list, a radio or the queue comes to it, and is dimmed
 * in song lists; playing it by hand still plays it. Newest first.
 */
object HiddenSongs {
    private const val PREF = "HiddenSongs"
    private const val KEY = "songs"

    var songs by mutableStateOf(load(com.music.spotui.di.Graph.app))
        private set
    private var ids by mutableStateOf(songs.map { it.id }.toSet())

    /** The song [justHidden] is offered to be taken back (the Undo snackbar of the app's root). */
    var justHidden by mutableStateOf<HiddenSong?>(null)

    fun isHidden(trackId: String): Boolean = trackId.isNotBlank() && trackId in ids

    fun hide(context: Context, song: SongsModel) {
        if (song.spotifyTrackId.isBlank() || isHidden(song.spotifyTrackId)) return
        val h = HiddenSong(song.spotifyTrackId, song.title, song.singer, song.coverUri)
        set(context, listOf(h) + songs)
        justHidden = h
    }

    fun show(context: Context, trackId: String) = set(context, songs.filterNot { it.id == trackId })

    private fun set(context: Context, list: List<HiddenSong>) {
        songs = list
        ids = list.map { it.id }.toSet()
        val arr = JSONArray().also { a ->
            list.forEach { a.put(JSONObject().put("id", it.id).put("title", it.title).put("singer", it.singer).put("cover", it.coverUri)) }
        }
        context.getSharedPreferences(PREF, Context.MODE_PRIVATE).edit().putString(KEY, arr.toString()).apply()
    }

    private fun load(context: Context): List<HiddenSong> {
        val raw = context.getSharedPreferences(PREF, Context.MODE_PRIVATE).getString(KEY, null) ?: return emptyList()
        return runCatching {
            val arr = JSONArray(raw)
            (0 until arr.length()).map { arr.getJSONObject(it).let { o -> HiddenSong(o.getString("id"), o.optString("title"), o.optString("singer"), o.optString("cover")) } }
        }.getOrDefault(emptyList())
    }
}

package com.music.spotui.data.preferences

import com.music.spotui.data.entity.SongsModel
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.json.Json

// The last session's queue (and the list it was played in, kept beside it) and the rule that decides who wins at launch, kept pure so they
// are tested without Android. The song itself lives in SongPlayer's "myspoti_last_track".

object LastSession {
    /** Where the saved session played: Spotify's own player, or the local player (an extension's stream, a download). */
    const val SOURCE_SPOTIFY = "spotify"
    const val SOURCE_LOCAL = "local"

    private const val MAX_QUEUE = 100
    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    /** The songs of the session's queue as stored; capped so the preferences stay small. */
    fun encodeQueue(songs: List<SongsModel>): String =
        json.encodeToString(ListSerializer(SongsModel.serializer()), songs.take(MAX_QUEUE))

    /** The stored queue, empty when missing or unreadable. */
    fun decodeQueue(raw: String?): List<SongsModel> {
        if (raw.isNullOrBlank()) return emptyList()
        return runCatching { json.decodeFromString(ListSerializer(SongsModel.serializer()), raw) }.getOrDefault(emptyList())
    }

    /**
     * The saved queue of the song [trackId]: [songs] from that song on, once each. The page's queue
     * can still list the song before it, and a queue read just after a skip belongs to the song
     * left: that one holds no [trackId] and is not saved with it. Empty when it does not hold it.
     */
    fun queueFor(trackId: String, songs: List<SongsModel>): List<SongsModel> {
        val at = songs.indexOfFirst { it.spotifyTrackId == trackId }
        if (trackId.isBlank() || at < 0) return emptyList()
        return songs.drop(at).distinctBy { it.spotifyTrackId.ifBlank { it.url } }
    }

    /**
     * Spotify's state at launch is older than the session saved from the local player: it still
     * shows the song played before and must not replace it. A state stamped after the save
     * (another device played since) or one that plays is real and wins.
     */
    fun engineStateIsStale(savedSource: String, savedAtMs: Long, engineTimestampMs: Long, enginePaused: Boolean): Boolean =
        savedSource == SOURCE_LOCAL && enginePaused && engineTimestampMs <= savedAtMs
}

package com.music.spotui.data.preferences

import android.content.Context
import com.music.spotui.data.entity.ArtistsModel
import com.music.spotui.data.entity.LibraryEntry
import org.json.JSONArray
import org.json.JSONObject

private const val PREF = "LibraryCache"

fun cacheLibraryEntries(context: Context, entries: List<LibraryEntry>) {
    val json = JSONArray().apply {
        entries.forEach { e ->
            put(JSONObject().apply {
                put("spotifyId", e.spotifyId)
                put("name", e.name)
                put("subtitle", e.subtitle)
                put("coverUri", e.coverUri)
                put("isPlaylist", e.isPlaylist)
                put("artists", e.artists)
                put("folderUri", e.folderUri)
                put("childCount", e.childCount)
                put("ownerUri", e.ownerUri)
            })
        }
    }.toString()
    context.getSharedPreferences(PREF, Context.MODE_PRIVATE)
        .edit().putString("entries", json).apply()
}

fun getCachedLibraryEntries(context: Context): List<LibraryEntry> = runCatching {
    val raw = context.getSharedPreferences(PREF, Context.MODE_PRIVATE)
        .getString("entries", null) ?: return emptyList()
    val arr = JSONArray(raw)
    (0 until arr.length()).map { i ->
        arr.getJSONObject(i).let { o ->
            LibraryEntry(
                spotifyId = o.getString("spotifyId"),
                name = o.getString("name"),
                subtitle = o.getString("subtitle"),
                coverUri = o.getString("coverUri"),
                isPlaylist = o.getBoolean("isPlaylist"),
                artists = o.optString("artists", ""),
                folderUri = o.optString("folderUri", ""),
                childCount = o.optInt("childCount", 0),
                ownerUri = o.optString("ownerUri", ""),
            )
        }
    }
}.getOrDefault(emptyList())

fun cacheFollowedArtists(context: Context, artists: List<ArtistsModel>) {
    val json = JSONArray().apply {
        artists.forEach { a ->
            put(JSONObject().apply {
                put("name", a.name)
                put("coverUri", a.coverUri)
                put("id", a.id)
            })
        }
    }.toString()
    context.getSharedPreferences(PREF, Context.MODE_PRIVATE)
        .edit().putString("followedArtists", json).apply()
}

fun getCachedFollowedArtists(context: Context): List<ArtistsModel> = runCatching {
    val raw = context.getSharedPreferences(PREF, Context.MODE_PRIVATE)
        .getString("followedArtists", null) ?: return emptyList()
    val arr = JSONArray(raw)
    (0 until arr.length()).map { i ->
        arr.getJSONObject(i).let { o ->
            ArtistsModel(
                name = o.getString("name"),
                coverUri = o.getString("coverUri"),
                id = o.optString("id", ""),
            )
        }
    }
}.getOrDefault(emptyList())

package com.music.spotui.data.preferences

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

/**
 * Settings > Library: the pinned "Local Files" row of the Library, shown unless turned off (asked
 * on Discord: "I do not have local files on my phone"). Hiding it touches no file and no playlist.
 */
object LocalFilesPref {
    private const val PREF = "library_prefs"
    private const val KEY = "local_files_shown"

    var shown by mutableStateOf(true)
        private set

    fun init(context: Context) {
        shown = context.getSharedPreferences(PREF, Context.MODE_PRIVATE).getBoolean(KEY, true)
    }

    fun set(context: Context, value: Boolean) {
        shown = value
        context.getSharedPreferences(PREF, Context.MODE_PRIVATE).edit().putBoolean(KEY, value).apply()
    }
}

package com.music.spotui.data.preferences

/*
 * The app's look: Classic (today's) or Immersive, picked during the onboarding.
 */

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

/** The two looks. [CLASSIC] is the default, so nothing changes for anyone who has not chosen. */
enum class Look {
    CLASSIC, IMMERSIVE;

    companion object {
        fun of(name: String?): Look = entries.firstOrNull { it.name == name } ?: CLASSIC
    }
}

object LookPref {
    private const val PREF = "settings_prefs"
    private const val KEY = "look"
    private const val KEY_CHOSEN = "look_chosen"
    private const val KEY_OFFERED = "look_offered"

    /** The chosen look, as Compose state: everything reading it redraws when it changes. */
    var look by mutableStateOf(Look.of(prefs(com.music.spotui.di.Graph.app).getString(KEY, null)))
        private set

    fun set(c: Context, value: Look) {
        look = value
        prefs(c).edit().putString(KEY, value.name).apply()
    }

    /** The look step of the onboarding was seen (new installs and updates alike). */
    fun isChosen(c: Context): Boolean = prefs(c).getBoolean(KEY_CHOSEN, false)
    fun setChosen(c: Context) {
        prefs(c).edit().putBoolean(KEY_CHOSEN, true).putBoolean(KEY_OFFERED, true).apply()
        offered = true
    }

    /**
     * The new-look popup was shown to an existing user (or the onboarding look step covered it), as
     * Compose state. The activity kept its own copy, read once at its start: the look step of the
     * onboarding saved "offered" but the copy stayed false, and the popup came up as soon as the
     * onboarding ended, asking the look a second time.
     */
    var offered by mutableStateOf(prefs(com.music.spotui.di.Graph.app).getBoolean(KEY_OFFERED, false))
        private set
    fun isOffered(c: Context): Boolean = prefs(c).getBoolean(KEY_OFFERED, false)
    fun setOffered(c: Context) {
        prefs(c).edit().putBoolean(KEY_OFFERED, true).apply()
        offered = true
    }
    fun clearOffered(c: Context) {
        prefs(c).edit().remove(KEY_OFFERED).apply()
        offered = false
    }

    private fun prefs(c: Context) = c.getSharedPreferences(PREF, Context.MODE_PRIVATE)
}

package com.music.spotui.data.preferences

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.setValue
import com.music.spotui.data.entity.SongsModel
import com.music.spotui.di.Graph
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneOffset

/** How a show page lists its episodes, besides the newest / oldest order. */
enum class EpisodeFilter {
    /** Spotify's own order. */
    ALL,
    /** Episodes not played yet first, the played ones after them (each group keeps its order). */
    UNPLAYED_FIRST,
    /** Played episodes are left out. */
    HIDE_PLAYED;

    fun next(): EpisodeFilter = entries[(ordinal + 1) % entries.size]

    /** [episodes] in this filter's order; [played] says which of them are finished. */
    fun apply(episodes: List<SongsModel>, played: (SongsModel) -> Boolean): List<SongsModel> = when (this) {
        ALL -> episodes
        UNPLAYED_FIRST -> episodes.sortedBy { if (played(it)) 1 else 0 }
        HIDE_PLAYED -> episodes.filterNot(played)
    }
}

/**
 * What the app remembers about podcasts on this phone: the episode filter chosen on a show page
 * (per show, the last choice for the shows not chosen yet), when each show was last opened, and
 * the date of the newest episode seen, for the "new episode" marks. Nothing is sent anywhere.
 */
object PodcastPrefs {
    private const val FILE = "podcast_state"
    /** The cheap "newest episode" check of a show is repeated at most this often. */
    private const val CHECK_EVERY_MS = 6 * 3_600_000L

    private fun prefs() = Graph.app.getSharedPreferences(FILE, Context.MODE_PRIVATE)

    /** Bumped on every change a mark depends on, so a composable reading [hasNew] redraws. */
    private var tick by mutableIntStateOf(0)

    fun filter(showId: String): EpisodeFilter {
        val p = prefs()
        val v = p.getString("filter:$showId", null) ?: p.getString("filter", null)
        return EpisodeFilter.entries.firstOrNull { it.name == v } ?: EpisodeFilter.ALL
    }

    fun setFilter(showId: String, filter: EpisodeFilter) {
        prefs().edit().putString("filter:$showId", filter.name).putString("filter", filter.name).apply()
    }

    /** The filter of "Your Episodes" (remembered on its own). */
    fun libraryFilter(): EpisodeFilter {
        val v = prefs().getString("filter:library", null)
        return EpisodeFilter.entries.firstOrNull { it.name == v } ?: EpisodeFilter.ALL
    }

    fun setLibraryFilter(filter: EpisodeFilter) {
        prefs().edit().putString("filter:library", filter.name).apply()
    }

    /** When [showId] was last opened (ms), 0 when never. */
    fun lastOpened(showId: String): Long = prefs().getLong("opened:$showId", 0L)

    /** The show page was opened: [newest] is its newest episode's release date seen there. */
    fun markOpened(showId: String, newest: String, followed: Boolean) {
        if (showId.isBlank()) return
        prefs().edit().apply {
            putLong("opened:$showId", System.currentTimeMillis())
            if (newest.isNotBlank()) putString("latest:$showId", newest)
            putBoolean("followed:$showId", followed)
        }.apply()
        tick++
    }

    /** The follow button was used on the show page. */
    fun setFollowed(showId: String, followed: Boolean) {
        if (showId.isBlank()) return
        prefs().edit().putBoolean("followed:$showId", followed).apply()
        tick++
    }

    fun isFollowed(showId: String): Boolean = prefs().getBoolean("followed:$showId", false)

    /** Release date of the newest episode known for [showId] ("" when never seen). */
    fun latest(showId: String): String = prefs().getString("latest:$showId", "").orEmpty()

    /** The cheap check is due: never done, or older than a few hours. */
    fun checkDue(showId: String): Boolean = System.currentTimeMillis() - prefs().getLong("checked:$showId", 0L) > CHECK_EVERY_MS

    /** The cheap check answered: [newest] is the newest episode's release date. */
    fun checked(showId: String, newest: String) {
        prefs().edit().apply {
            putLong("checked:$showId", System.currentTimeMillis())
            if (newest > latest(showId)) putString("latest:$showId", newest)
        }.apply()
        tick++
    }

    /** True when [release] is after [since] (ms); a date without a time counts from its start. */
    fun releasedAfter(release: String, since: Long): Boolean {
        if (release.isBlank() || since <= 0L) return false
        // Spotify gives a plain date ("2026-10-27") nearly always: no exception for the common case.
        val ms = (if (release.length > 10) runCatching { Instant.parse(release).toEpochMilli() }.getOrNull() else null)
            ?: runCatching { LocalDate.parse(release.take(10)).atStartOfDay().toInstant(ZoneOffset.UTC).toEpochMilli() }.getOrNull()
            ?: return false
        return ms > since
    }

    /** The cheap check for [showId] when it is due: one episode asked for, at most every few hours. */
    suspend fun refresh(showId: String) {
        if (!isFollowed(showId) || lastOpened(showId) == 0L || !checkDue(showId)) return
        checked(showId, Graph.api.latestEpisodeDate(showId))
    }

    /** A followed show has an episode released since the user last opened it. */
    fun hasNew(showId: String): Boolean {
        @Suppress("UNUSED_VARIABLE") val read = tick
        if (!isFollowed(showId)) return false
        return releasedAfter(latest(showId), lastOpened(showId))
    }
}

