package com.music.spotui.data.preferences

import android.content.SharedPreferences

/**
 * Settings that belong to the Spotify account in use (the accounts kept on the phone, each its
 * WebView profile): the first account keeps the keys it always had, another one reads and writes
 * `key@profile`, and goes on with the first account's value until it sets its own. Asked: the
 * quality and the extensions' settings follow the account, not the phone.
 */
object ProfilePrefs {
    /** The active account's profile; the first one before the engine has started. */
    fun profile(): String = runCatching {
        val runtime = app.myspoti.host.android.MyspotiRuntime
        if (runtime.isStarted) runtime.host.accounts.list.value.active else null
    }.getOrNull() ?: app.myspoti.host.android.AccountList.DEFAULT_PROFILE

    /** [base] as the active account stores it. */
    fun key(base: String): String = profile().let { if (it == app.myspoti.host.android.AccountList.DEFAULT_PROFILE) base else "$base@$it" }

    fun getString(p: SharedPreferences, base: String, default: String?): String? {
        val k = key(base)
        return if (k != base && p.contains(k)) p.getString(k, default) else p.getString(base, default)
    }

    fun getBoolean(p: SharedPreferences, base: String, default: Boolean): Boolean {
        val k = key(base)
        return if (k != base && p.contains(k)) p.getBoolean(k, default) else p.getBoolean(base, default)
    }
}

package com.music.spotui.data.preferences

/*
 * Sound quality: what the Web Player streams, and how downloads are saved.
 */

import android.content.Context
import kotlinx.coroutines.launch

private const val PREF = "settings_prefs"
private const val KEY_STREAMING = "streaming_quality"
private const val KEY_CHOSEN = "quality_chosen"
private const val KEY_STREAMING_CELL = "streaming_quality_cellular"
private const val KEY_CANVAS_WIFI = "canvas_wifi_only"

/**
 * The Web Player's own streaming levels (its "Streaming quality" setting): 24, 96 and
 * 160 kbit/s. Only the levels a free account gets; "very_high" (320) is Premium's.
 */
enum class StreamingQuality(val level: String) {
    AUTO("auto"), LOW("low"), NORMAL("normal"), HIGH("high"),
    /** 256 kbit/s: the Web Player gives it to Premium accounts only (offered then, see StreamingQualityPicker). */
    VERY_HIGH("very_high");

    companion object {
        fun of(level: String?): StreamingQuality = entries.firstOrNull { it.level == level } ?: AUTO
    }
}

/**
 * How a downloaded song is saved: not at all, small (AAC re-encoded from the checked FLAC),
 * FLAC 16-bit (CD), or FLAC 24-bit when it exists.
 */
enum class DownloadQuality {
    OFF, SMALL, CD, HI_RES,
    /** Asked when a download starts (once for a whole playlist or album). */
    ASK;

    companion object {
        /** A quality a file can be saved in ([ASK] and [OFF] are not); null when unknown. */
        fun saved(name: String?): DownloadQuality? = entries.firstOrNull { it.name == name }?.takeIf { it != ASK && it != OFF }
    }
}

/**
 * The level for Wi-Fi, or for mobile data ([cellular]), as the official app's two settings.
 * Mobile data follows the Wi-Fi level until it is set on its own.
 */
fun getStreamingQuality(c: Context, cellular: Boolean = false): StreamingQuality {
    // The account's own levels (see ProfilePrefs).
    val wifi = ProfilePrefs.getString(prefs(c), KEY_STREAMING, null)
    return StreamingQuality.of(if (cellular) ProfilePrefs.getString(prefs(c), KEY_STREAMING_CELL, null) ?: wifi else wifi)
}

/** Saves the level for that network and hands the one for the current network to the player. */
fun setStreamingQuality(c: Context, q: StreamingQuality, cellular: Boolean = false) {
    prefs(c).edit().putString(ProfilePrefs.key(if (cellular) KEY_STREAMING_CELL else KEY_STREAMING), q.level).apply()
    applyStreamingQuality(c)
}

/** Gives the current network's level to the Web Player (at start and when the network changes); harmless before it is up. */
fun applyStreamingQuality(c: Context) {
    val runtime = app.myspoti.host.android.MyspotiRuntime
    if (!runtime.isStarted) return
    val q = getStreamingQuality(c, cellular = com.music.spotui.data.DataSaver.metered)
    runtime.scope.launch { runtime.spotify.player.setAudioQuality(q.level) }
}

/** Canvas (the looping videos) only on Wi-Fi: they cost data on every song. */
fun isCanvasWifiOnly(c: Context): Boolean = prefs(c).getBoolean(KEY_CANVAS_WIFI, false)
fun setCanvasWifiOnly(c: Context, on: Boolean) = prefs(c).edit().putBoolean(KEY_CANVAS_WIFI, on).apply()

fun getDownloadQuality(c: Context): DownloadQuality = when {
    !isDownloadsEnabled(c) -> DownloadQuality.OFF
    isAskDownloadQuality(c) -> DownloadQuality.ASK
    isSmallDownloads(c) -> DownloadQuality.SMALL
    isHiRes(c) -> DownloadQuality.HI_RES
    else -> DownloadQuality.CD
}

fun setDownloadQuality(c: Context, q: DownloadQuality) {
    setDownloadsEnabled(c, q != DownloadQuality.OFF)
    setHiRes(c, q == DownloadQuality.HI_RES)
    setSmallDownloads(c, q == DownloadQuality.SMALL)
    setAskDownloadQuality(c, q == DownloadQuality.ASK)
}

/** The quality step of the onboarding was seen (new installs and updates alike). */
fun isQualityChosen(c: Context): Boolean = prefs(c).getBoolean(KEY_CHOSEN, false)
fun setQualityChosen(c: Context) = prefs(c).edit().putBoolean(KEY_CHOSEN, true).apply()

private fun prefs(c: Context) = c.getSharedPreferences(PREF, Context.MODE_PRIVATE)

package com.music.spotui.data.preferences

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

/**
 * One "Recent searches" entry — Spotify-style: not the typed query but the
 * actual item the user opened from the results (song / artist / album / show).
 * Carries enough payload to re-launch the item on tap.
 */
data class RecentItem(
    val type: String,            // "song" | "artist" | "album" | "show"
    val key: String,             // stable id for dedupe (spotify id, or name)
    val name: String,
    val singer: String = "",     // artist line (songs/albums)
    val image: String = "",
    // Song-only payload so a tap can replay it.
    val songId: Int = -1,
    val songAlbum: String = "",
    val songUrl: String = "",
    val spotifyTrackId: String = "",
    val explicit: Boolean = false,
    val durationMs: Int = 0,
)

/** [this], a search's song the user played, as the recent search to keep. */
fun com.music.spotui.data.entity.SongsModel.toRecentItem() = RecentItem(
    type = "song",
    key = spotifyTrackId.ifBlank { url },
    name = title,
    singer = singer,
    image = coverUri,
    songId = id,
    songAlbum = album,
    songUrl = url,
    spotifyTrackId = spotifyTrackId,
    explicit = explicit,
    durationMs = durationMs,
)

/**
 * A recent song as the song to play or queue again; null for any other kind of item. A song kept
 * with its Spotify id is played by that id, whatever play key was saved with it.
 */
fun RecentItem.toSong(): com.music.spotui.data.entity.SongsModel? {
    if (type != "song") return null
    val byId = { com.music.spotui.di.SongPlayer.buildSpotifyPlayQuery(spotifyTrackId, name, singer) }
    val url = when {
        songUrl.isBlank() -> byId()
        spotifyTrackId.isNotBlank() && !songUrl.startsWith("spotify:track:") -> byId()
        else -> songUrl
    }
    return com.music.spotui.data.entity.SongsModel(
        songId, name, songAlbum, singer, image, url, spotifyTrackId,
        explicit = explicit, durationMs = durationMs,
    )
}

private const val PREF = "RecentItems"
private const val KEY = "items"
private const val MAX_ITEMS = 20

private fun RecentItem.toJson(): JSONObject = JSONObject().apply {
    put("type", type); put("key", key); put("name", name); put("singer", singer)
    put("image", image); put("songId", songId); put("songAlbum", songAlbum)
    put("songUrl", songUrl); put("spotifyTrackId", spotifyTrackId)
    put("explicit", explicit); put("durationMs", durationMs)
}

private fun JSONObject.toRecentItem(): RecentItem = RecentItem(
    type = optString("type"), key = optString("key"), name = optString("name"),
    singer = optString("singer"), image = optString("image"),
    songId = optInt("songId", -1), songAlbum = optString("songAlbum"),
    songUrl = optString("songUrl"), spotifyTrackId = optString("spotifyTrackId"),
    explicit = optBoolean("explicit", false), durationMs = optInt("durationMs", 0),
)

fun getRecentItems(context: Context): List<RecentItem> {
    val raw = context.getSharedPreferences(PREF, Context.MODE_PRIVATE).getString(KEY, null)
        ?: return emptyList()
    return runCatching {
        val arr = JSONArray(raw)
        (0 until arr.length()).map { arr.getJSONObject(it).toRecentItem() }
    }.getOrDefault(emptyList())
}

private fun save(context: Context, items: List<RecentItem>) {
    val arr = JSONArray().also { a -> items.forEach { a.put(it.toJson()) } }
    context.getSharedPreferences(PREF, Context.MODE_PRIVATE)
        .edit().putString(KEY, arr.toString()).apply()
}

fun addRecentItem(context: Context, item: RecentItem) {
    if (item.name.isBlank()) return
    val rest = getRecentItems(context).filterNot { it.type == item.type && it.key == item.key }
    save(context, (listOf(item) + rest).take(MAX_ITEMS))
}

fun removeRecentItem(context: Context, item: RecentItem) {
    save(context, getRecentItems(context).filterNot { it.type == item.type && it.key == item.key })
}

fun clearRecentItems(context: Context) {
    context.getSharedPreferences(PREF, Context.MODE_PRIVATE).edit().remove(KEY).apply()
}

